<script>
document.addEventListener('DOMContentLoaded',()=>{const industry=document.querySelector('[data-industry-select]');const subcategory=document.querySelector('[data-subcategory-select]');if(!industry||!subcategory)return;const filter=()=>{for(const option of subcategory.options){if(!option.value)continue;option.hidden=option.dataset.industry!==industry.value;if(option.selected&&option.hidden)subcategory.value='';}};industry.addEventListener('change',filter);filter();});
</script>
